// GHL -> CRM stage sync. GHL owns pipeline stage; this mirrors it into
// plumbing_leads. Design: docs/GHL_SYNC.md.
//
// BEFORE ACTIVATING, replace the three placeholders below:
//   SUPABASE_URL  = https://phtmarvmovozydxipmat.supabase.co  (the CRM project)
//   SERVICE_KEY   = Supabase Dashboard -> Settings -> API Keys -> service_role (secret)
//   MIRROR_KEY    = any long random string you invent; paste the SAME value as the
//                   X-Mirror-Key header in the GHL workflow's Custom Webhook action.
//
// GHL-side setup (per sub-account): a Workflow with trigger "Opportunity status
// changed" / "Opportunity stage changed" (exact names vary) -> action
// "Custom Webhook" -> POST to this workflow's production URL, header
// X-Mirror-Key: <MIRROR_KEY>, and the opportunity + contact merge fields in the body.

const SUPABASE_URL = 'PASTE_PROJECT_URL_HERE';
const SERVICE_KEY = 'PASTE_SERVICE_ROLE_KEY_HERE';
const MIRROR_KEY = 'PASTE_SHARED_SECRET_HERE';

const req = items[0].json;
const headersIn = req.headers ?? {};
const body = req.body ?? req;

// --- 0. Authenticate the delivery -----------------------------------------
if ((headersIn['x-mirror-key'] ?? '') !== MIRROR_KEY) {
  throw new Error('Rejected: bad X-Mirror-Key.');
}

const sbHeaders = (extra = {}) => ({
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  'Content-Type': 'application/json',
  ...extra,
});

// --- 1. Normalize (field paths may need adjusting to your GHL workflow body) -
const opp = body.opportunity ?? body;
const contact = body.contact ?? {};
const locationId = body.locationId ?? body.location_id ?? opp.location_id;
const oppId = opp.id ?? body.opportunity_id;
const pipelineId = opp.pipeline_id ?? body.pipeline_id;
const stageId = opp.pipeline_stage_id ?? opp.stage_id ?? body.stage_id;
const status = String(opp.status ?? '').toLowerCase();
const eventType = body.event_type ?? 'opportunity.stage_changed';
const srcTs = body.updated_at ?? opp.date_updated ?? opp.updated_at ?? new Date().toISOString();
const fullName =
  [contact.first_name, contact.last_name].filter(Boolean).join(' ') || body.contact_name || null;
const address =
  [contact.address1, contact.city, contact.state, contact.postal_code].filter(Boolean).join(', ') ||
  null;

if (!locationId || !oppId) throw new Error('Payload missing locationId or opportunity id.');

const eventKey = [locationId, eventType, oppId, stageId || status, srcTs].join(':');

// --- 2. Inbox: log every delivery, idempotently (audit + replay) -----------
await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/ghl_events?on_conflict=event_key`,
  headers: sbHeaders({ Prefer: 'resolution=merge-duplicates,return=minimal' }),
  body: { event_key: eventKey, location_id: locationId, event_type: eventType, payload: body },
  json: true,
});

// --- 3. Map the GHL stage to the mirror stage (never guess from names) -----
let targetStage = null;
let subAccountId = null;

if (pipelineId && stageId) {
  const mapRows = await this.helpers.httpRequest({
    method: 'GET',
    url:
      `${SUPABASE_URL}/rest/v1/ghl_stage_map` +
      `?ghl_pipeline_id=eq.${encodeURIComponent(pipelineId)}` +
      `&ghl_stage_id=eq.${encodeURIComponent(stageId)}` +
      `&select=sub_account_id,pipeline_stage`,
    headers: sbHeaders(),
    json: true,
  });
  targetStage = mapRows?.[0]?.pipeline_stage ?? null;
  subAccountId = mapRows?.[0]?.sub_account_id ?? null;
}

// Safety net per design doc §7: a 'won' opportunity is booked even if its
// stage row is unmapped.
if (!targetStage && status === 'won') targetStage = 'booked';

if (!targetStage) {
  return [{ json: { skipped: 'unmapped_stage', pipeline_id: pipelineId, stage_id: stageId, locationId } }];
}

// --- 4. Ordering guard: stale deliveries degrade to no-ops ------------------
const leads = await this.helpers.httpRequest({
  method: 'GET',
  url:
    `${SUPABASE_URL}/rest/v1/plumbing_leads` +
    `?ghl_opportunity_id=eq.${encodeURIComponent(oppId)}` +
    `&select=lead_id,ghl_synced_at,pipeline_stage`,
  headers: sbHeaders(),
  json: true,
});
const lead = leads?.[0];
const incomingMs = new Date(srcTs).getTime();
const currentMs = lead?.ghl_synced_at ? new Date(lead.ghl_synced_at).getTime() : 0;
const appliedAt = new Date(incomingMs).toISOString();

if (lead && incomingMs <= currentMs) {
  return [{ json: { skipped: 'stale_event', ghl_opportunity_id: oppId } }];
}

// --- 5. Apply: update stage only. Call-data columns are never touched ------
if (lead) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/plumbing_leads?ghl_opportunity_id=eq.${encodeURIComponent(oppId)}`,
    headers: sbHeaders({ Prefer: 'return=minimal' }),
    body: { pipeline_stage: targetStage, ghl_synced_at: appliedAt },
    json: true,
  });
  return [{ json: { updated: oppId, pipeline_stage: targetStage } }];
}

// No matching call-created row: insert a stub so GHL truth is never dropped.
// The linking heuristic (phone match) stays out of n8n — a human merges if
// needed; a duplicate beats a wrong link (design doc §6).
if (!subAccountId) {
  return [{ json: { skipped: 'no_sub_account_mapping', locationId, ghl_opportunity_id: oppId } }];
}

await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/plumbing_leads?on_conflict=ghl_opportunity_id`,
  headers: sbHeaders({ Prefer: 'resolution=merge-duplicates,return=minimal' }),
  body: {
    ghl_opportunity_id: oppId,
    sub_account_id: subAccountId,
    customer_name: fullName ?? 'Unknown',
    customer_phone: contact.phone ?? '',
    customer_address: address ?? '',
    plumbing_issue: '(created from GHL — no call data)',
    emergency_level: 'standard',
    pipeline_stage: targetStage,
    call_id: null,
    transcript: null,
    ghl_synced_at: appliedAt,
  },
  json: true,
});

return [{ json: { inserted_stub: oppId, pipeline_stage: targetStage } }];
